#!/usr/bin/env python3
"""Generate the terminal's character width tables from Unicode data.

termCharWidth (src/TerminalStream.cpp) gives each code point the columns it
takes on a terminal. Its tables are written by this script, between the
"generated by tools/gen-term-width.py" markers in that file, from three
files of the Unicode Character Database, which are not kept in the repo:

    https://www.unicode.org/Public/<version>/ucd/UnicodeData.txt
    https://www.unicode.org/Public/<version>/ucd/EastAsianWidth.txt
    https://www.unicode.org/Public/<version>/ucd/emoji/emoji-data.txt

Fetch them into a folder of their own, then run from the repo root:

    python3 -I tools/gen-term-width.py <folder> [src/TerminalStream.cpp]

The rules, as wcwidth and the terminals that follow Unicode use them:

  0 columns: general categories Mn, Me and Cf (combining marks, enclosing
    marks, format characters such as ZWJ and the bidi controls), except
    U+00AD SOFT HYPHEN, which shows; the Hangul Jamo medial vowels and
    final consonants (U+1160..U+11FF, U+D7B0..U+D7FF), which join the
    initial consonant before them into one syllable; and the emoji
    modifiers U+1F3FB..U+1F3FF, which join the emoji before them.
  2 columns: East_Asian_Width W or F, and the unassigned code points the
    file says default to W (the CJK ideograph blocks, planes 2 and 3),
    unless the rule above made them 0.
  1 column: everything else.

It also writes the Extended_Pictographic ranges, which say whether a
character after a zero width joiner joins the emoji before it.
"""
import os
import re
import sys

BEGIN = "// ---- generated by tools/gen-term-width.py: begin"
END = "// ---- generated by tools/gen-term-width.py: end"


def ranges_of(lines, want):
    """(first, last) pairs of the lines whose field 1 is in `want`."""
    out = []
    for line in lines:
        line = line.split("#", 1)[0].strip()
        if not line:
            continue
        cps, value = [f.strip() for f in line.split(";")[:2]]
        if value not in want:
            continue
        if ".." in cps:
            a, b = cps.split("..")
            out.append((int(a, 16), int(b, 16)))
        else:
            out.append((int(cps, 16), int(cps, 16)))
    return out


def merge(ranges):
    out = []
    for a, b in sorted(ranges):
        if out and a <= out[-1][1] + 1:
            out[-1] = (out[-1][0], max(out[-1][1], b))
        else:
            out.append((a, b))
    return out


def subtract(ranges, holes):
    """The code points of `ranges` not in `holes`, as ranges."""
    out = []
    holes = merge(holes)
    for a, b in merge(ranges):
        start = a
        for h0, h1 in holes:
            if h1 < start or h0 > b:
                continue
            if h0 > start:
                out.append((start, h0 - 1))
            start = max(start, h1 + 1)
            if start > b:
                break
        if start <= b:
            out.append((start, b))
    return out


def general_categories(path):
    """Code point ranges per general category, ranges ("<..., First>" and
    "<..., Last>" pairs) included."""
    cats = {}
    first = None
    with open(path, encoding="utf-8") as f:
        for line in f:
            fields = line.split(";")
            cp, name, cat = int(fields[0], 16), fields[1], fields[2]
            if name.endswith(", First>"):
                first = cp
                continue
            a = first if name.endswith(", Last>") else cp
            first = None
            cats.setdefault(cat, []).append((a, cp))
    return cats


def version_of(path):
    with open(path, encoding="utf-8") as f:
        head = f.readline()
    m = re.search(r"(\d+\.\d+\.\d+)", head)
    return m.group(1) if m else "unknown"


def table(name, ranges, comment):
    rows = ["// " + comment, "const uint32_t %s[][2] = {" % name]
    items = ["{0x%04X, 0x%04X}," % r for r in ranges]
    line = "   "
    for item in items:
        if len(line) + 1 + len(item) > 96:
            rows.append(line)
            line = "   "
        line += " " + item
    if line.strip():
        rows.append(line)
    rows.append("};")
    return "\n".join(rows)


def main():
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    folder = sys.argv[1]
    target = sys.argv[2] if len(sys.argv) > 2 else os.path.join("src", "TerminalStream.cpp")
    ucd = os.path.join(folder, "UnicodeData.txt")
    eaw_path = os.path.join(folder, "EastAsianWidth.txt")
    emoji_path = os.path.join(folder, "emoji-data.txt")
    version = version_of(eaw_path)

    cats = general_categories(ucd)
    zero = []
    for cat in ("Mn", "Me", "Cf"):
        zero += cats.get(cat, [])
    zero = subtract(zero, [(0x00AD, 0x00AD)])
    zero += [(0x1160, 0x11FF), (0xD7B0, 0xD7FF), (0x1F3FB, 0x1F3FF)]
    zero = merge(zero)

    with open(eaw_path, encoding="utf-8") as f:
        wide = ranges_of(f, {"W", "F"})
    wide += [(0x3400, 0x4DBF), (0x4E00, 0x9FFF), (0xF900, 0xFAFF),
             (0x20000, 0x2FFFD), (0x30000, 0x3FFFD)]
    wide = subtract(wide, zero)

    with open(emoji_path, encoding="utf-8") as f:
        pict = merge(ranges_of(f, {"Extended_Pictographic"}))

    # termCharWidth answers 1 below this without looking.
    fast = min(zero[0][0], wide[0][0])
    assert fast >= 0x0300, hex(fast)

    body = "\n".join([
        BEGIN,
        "// From Unicode %s (UnicodeData.txt, EastAsianWidth.txt, emoji-data.txt)." % version,
        "// Do not edit by hand: run the script (its header says how).",
        "namespace {",
        "",
        "const uint32_t kFirstNotNarrow = 0x%04X;" % fast,
        "",
        table("kZeroWidth", zero,
              "Mn, Me and Cf but U+00AD; Hangul medial and final jamo; emoji modifiers."),
        "",
        table("kWide", wide, "East_Asian_Width W and F, and the blocks that default to W."),
        "",
        table("kExtendedPictographic", pict, "Extended_Pictographic."),
        "",
        "}  // namespace",
        END,
    ])

    with open(target, encoding="utf-8") as f:
        text = f.read()
    start, stop = text.find(BEGIN), text.find(END)
    if start < 0 or stop < start:
        sys.exit("%s has no generated region (the %r and %r lines)" % (target, BEGIN, END))
    text = text[:start] + body + text[stop + len(END):]
    with open(target, "w", encoding="utf-8") as f:
        f.write(text)
    print("%s: Unicode %s, %d zero-width, %d wide and %d pictographic ranges"
          % (target, version, len(zero), len(wide), len(pict)))


if __name__ == "__main__":
    main()
